internal sealed class GatheringSettingsPane:Grid {
 readonly EnergyOverlay owner;readonly Window window;readonly StackPanel controls=new StackPanel();readonly Image preview=new Image{Height=125,Stretch=Stretch.Uniform};readonly List<Action<GatheringOptions>> reloaders=new List<Action<GatheringOptions>>();readonly CheckBox enabled=new CheckBox();readonly TextBlock state=SettingsVisual.Text("",11,"#91B29F");readonly GatheringPainter painter=new GatheringPainter();GatheringOptions shown;string language;bool loading;int remaining=2;
 internal GatheringSettingsPane(EnergyOverlay owner,Window window){this.owner=owner;this.window=window;var scroller=new ScrollViewer{Content=controls,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,HorizontalScrollBarVisibility=ScrollBarVisibility.Disabled};scroller.SetResourceReference(FrameworkElement.StyleProperty,"SlimScroll");Children.Add(scroller);var activation=Row("Enable gathering widget");Grid.SetColumn(enabled,1);activation.Children.Add(enabled);controls.Children.Add(activation);enabled.Click+=delegate{Change(o=>o.Enabled=enabled.IsChecked==true);};
 var group=Group("PREVIEW");group.Children.Add(preview);var slider=new Slider{Minimum=0,Maximum=3,Value=2,TickFrequency=1,IsSnapToTickEnabled=true,IsMoveToPointEnabled=true};AutomationProperties.SetName(slider,"Preview remaining uses");var row=Row("Preview remaining uses");Grid.SetColumn(slider,1);slider.Width=200;row.Children.Add(slider);group.Children.Add(row);slider.ValueChanged+=delegate{remaining=(int)slider.Value;shown=null;Reload();};group.Children.Add(state);
 group=Group("BEHAVIOR");group.Children.Add(SettingsVisual.Text("Shows the resource you gather with F. Uses are received from resource state, including partially used nodes. A gathering attempt can consume a use even when it fails or is cancelled. Unlock widgets in General to move or resize.",12,"#A7ADBA"));group.Children.Add(SettingsVisual.Text("Open the Helper before entering your character. Already loaded resources may need to leave view and load again. Three-use resources are supported; unknown profiles stay hidden.",11,"#8994A6"));
 group=Group("APPEARANCE");Toggle(group,"Show resource name",o=>o.Name,(o,v)=>o.Name=v);Toggle(group,"Show resource type",o=>o.Type,(o,v)=>o.Type=v);Toggle(group,"Show remaining count",o=>o.Count,(o,v)=>o.Count=v);Number(group,"Whole widget scale","%",50,250,o=>o.Scale,(o,v)=>o.Scale=v);Number(group,"Name text size","px",10,48,o=>o.FontSize,(o,v)=>o.FontSize=v);Number(group,"Type text size","px",10,30,o=>o.TypeSize,(o,v)=>o.TypeSize=v);Number(group,"Count text size","px",10,30,o=>o.CountSize,(o,v)=>o.CountSize=v);Number(group,"Bar height","px",4,40,o=>o.BarHeight,(o,v)=>o.BarHeight=v);Number(group,"Segment spacing","px",2,24,o=>o.Gap,(o,v)=>o.Gap=v);Number(group,"Widget opacity","%",0,100,o=>o.Opacity,(o,v)=>o.Opacity=v);Number(group,"Empty segment opacity","%",0,100,o=>o.EmptyOpacity,(o,v)=>o.EmptyOpacity=v);Toggle(group,"Segment glow",o=>o.Glow,(o,v)=>o.Glow=v);Number(group,"Glow intensity","%",0,100,o=>o.GlowPercent,(o,v)=>o.GlowPercent=v,o=>o.Glow);Toggle(group,"Black text outline",o=>o.Outline,(o,v)=>o.Outline=v);Number(group,"Outline thickness","px",1,5,o=>o.OutlineWidth,(o,v)=>o.OutlineWidth=v,o=>o.Outline);Color(group,"Filled segment color",o=>o.Color,(o,v)=>o.Color=v);Color(group,"Empty segment color",o=>o.EmptyColor,(o,v)=>o.EmptyColor=v);Color(group,"Name color",o=>o.TextColor,(o,v)=>o.TextColor=v);Color(group,"Type and count color",o=>o.TypeColor,(o,v)=>o.TypeColor=v);
 group=Group("POSITION & SIZE");Number(group,"Horizontal position","px",-100000,100000,o=>o.Bounds.X,(o,v)=>{var b=o.Bounds;b.X=v;o.Bounds=b;});Number(group,"Vertical position","px",-100000,100000,o=>o.Bounds.Y,(o,v)=>{var b=o.Bounds;b.Y=v;o.Bounds=b;});Number(group,"Width","px",180,1200,o=>o.Bounds.Width,(o,v)=>{var b=o.Bounds;b.Width=v;o.Bounds=b;});
 group=Group("RESOURCE DATA");group.Children.Add(SettingsVisual.Text("Names use an offline ID catalogue. Specific types are shown when confirmed; otherwise an available broad group is used. Missing food subtypes stay blank. Three uses is the validated gathering rule, not an enemy-health maximum.",11,"#8994A6"));Reload();}
 Grid Row(string label){var g=new Grid{Margin=new Thickness(0,5,0,5),MinHeight=35};g.ColumnDefinitions.Add(new ColumnDefinition());g.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});g.Children.Add(SettingsVisual.Text(label));return g;}
 StackPanel Group(string title){controls.Children.Add(SettingsVisual.Text(title,10,"#929CAD"));var panel=new StackPanel();controls.Children.Add(SettingsVisual.Card(panel,new Thickness(16,10,16,10)));return panel;}
 void Change(Action<GatheringOptions> action){if(loading)return;var c=owner.Configuration;action(c.Crafting);c.Crafting.Normalize();owner.ApplyConfiguration(c);}
 void Toggle(StackPanel group,string label,Func<GatheringOptions,bool> read,Action<GatheringOptions,bool> write){var row=Row(label);var box=new CheckBox();AutomationProperties.SetName(box,label);Grid.SetColumn(box,1);row.Children.Add(box);group.Children.Add(row);box.Click+=delegate{Change(o=>write(o,box.IsChecked==true));};reloaders.Add(o=>box.IsChecked=read(o));}
 void Number(StackPanel group,string label,string unit,int min,int max,Func<GatheringOptions,int> read,Action<GatheringOptions,int> write,Func<GatheringOptions,bool> active=null){var row=Row(label);var holder=new StackPanel{Orientation=Orientation.Horizontal};var n=new SettingsNumber(label,min,max,0,1);holder.Children.Add(n);holder.Children.Add(SettingsVisual.Text(unit,11,"#8994A6"));Grid.SetColumn(holder,1);row.Children.Add(holder);group.Children.Add(row);n.Changed+=delegate{Change(o=>write(o,(int)n.Value));};reloaders.Add(o=>{n.Value=read(o);n.IsEnabled=active==null||active(o);});}
 void Color(StackPanel group,string label,Func<GatheringOptions,string> read,Action<GatheringOptions,string> write){var row=Row(label);var button=SettingsVisual.Button("Choose color",delegate{var picker=new HelperColorPicker(read(owner.Configuration.Crafting),label,owner.Language){Owner=window};if(picker.ShowDialog()==true)Change(o=>write(o,picker.SelectedHex));});Grid.SetColumn(button,1);row.Children.Add(button);group.Children.Add(row);reloaders.Add(o=>{button.Content=read(o);button.Foreground=SettingsVisual.Brush(read(o));});}
 internal void Reload(){if(shown!=null&&GatheringOptions.Same(shown,owner.Configuration.Crafting)&&language==owner.Language)return;loading=true;try{var o=owner.Configuration.Crafting;enabled.IsChecked=o.Enabled;for(int i=1;i<controls.Children.Count;i++)((UIElement)controls.Children[i]).IsEnabled=o.Enabled;preview.Opacity=o.Enabled?1:.35;foreach(var reload in reloaders)reload(o);var sample=o.Copy();sample.Scale=100;sample.Bounds=new System.Drawing.Rectangle(0,0,456,100);using(var bitmap=painter.Render(sample,owner.Language,1500045,remaining,false))preview.Source=SettingsVisual.Bitmap(bitmap);state.Text=remaining+" / 3 · "+UiLanguage.Text("Preview only",owner.Language);shown=o.Copy();language=owner.Language;UiLanguage.Apply(this,language);}finally{loading=false;}}
 internal void Release(){preview.Source=null;painter.Dispose();}
 internal void Verify(string root){Reload();if(enabled.IsChecked!=owner.Configuration.Crafting.Enabled)throw new Exception("Crafting activation must reflect its own options");SettingsVisual.RenderPreview(window,System.IO.Path.Combine(root,"designs","settings-crafting.png"));}
}
